export const getDeleteRelationUrl = (listId: string,
    itemId: string,
    params: DeleteRelationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/tasks-api/lists/${listId}/items/${itemId}/relations?${stringifiedParams}` : `/tasks-api/lists/${listId}/items/${itemId}/relations`
}

